def compute(vars):
    niat = vars["Net Income After Taxes (NIAT)"]
    revenue = vars["Revenue"]
    multiplier = vars["100"]

    trace = {
        "Net Income After Taxes (NIAT)": niat,
        "Revenue": revenue,
        "100": multiplier,
    }

    if niat is None or revenue is None or multiplier is None:
        return {
            "value": None,
            "trace": {
                **trace,
                "output_meta": {
                    "currency": None,
                    "scale": None,
                    "unit": "percentage",
                },
            },
        }

    try:
        net_profit_margin = (niat / revenue) * multiplier
    except ZeroDivisionError:
        return None

    return {
        "value": net_profit_margin,
        "trace": {
            **trace,
            "x0": niat,
            "x1": revenue,
            "x2": multiplier,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage",
            },
        },
    }
